"""docich#4645: the card list's draw frames are a bounded open transition,
not a melee return; a picker box over the HP panel still selects."""
from pathlib import Path

import pytest

from docich.hanjuku_speedrun import hanjuku_policy as p
from docich.hanjuku_speedrun.hanjuku_font import TextLine
from docich.hanjuku_speedrun.hanjuku_pixels import read_png
from docich.hanjuku_speedrun.hanjuku_screen import parse
from docich.hanjuku_speedrun.hanjuku.os_layer.commands import _battle_menu_to
from docich.hanjuku_speedrun.hanjuku.os_layer.readers import ALL_CARD_NAMES, _options
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import _card_picker_rows

from test_hanjuku_card_damage_gate import cards, memory, panel

FIXTURES = Path(__file__).parent.parent / 'fixtures/hanjuku'


def transition_memory():
    # ゼンマイン (32 dmg) vs クミン 27 HP without soldiers: a lethal pick.
    return memory('ゼンマイン', soldiers=(0, 0))


def transition_panel(mem):
    return panel(mem, soldiers=(0, 0))


def picker_panel(mem, *names, cursor=176):
    """A battle-classified panel whose lower-right box reads picker rows."""
    screen = transition_panel(mem)
    rows = [TextLine(176 + 16 * i, tuple((176 + 8 * j, ch) for j, ch in enumerate(name)))
            for i, name in enumerate(names)]
    screen.lines = list(rows)
    screen.menu_rows = list(rows)
    screen.menu_cursor = cursor
    screen.text = ''.join(names)
    return screen


@pytest.mark.parametrize('stage', ['down', 'list'])
def test_open_transition_battle_frames_hold_the_flow_until_the_list_arrives(stage):
    # g1190-local ch1: きりふだ選択から一覧の描画まで数観測掛かる。間の実戦闘
    # パネルは白兵復帰ではなく開き途中なので、有界の範囲ではフローを保持する。
    mem = transition_memory()
    cur = mem['battle']
    cur['card_flow']['stage'] = stage
    for _ in range(p.CARD_LIST_OPEN_WAITS - 1):
        assert p.battle_step(transition_panel(mem), mem) == []
        assert cur['card_flow']['card'] == 'ゼンマイン'
    assert p.card_list_step(cards(['ゼンマイン']), mem) == [p.pad('a')]
    assert cur['cards_selected'] == ['ゼンマイン']
    assert cur['card_flow']['stage'] == 'announce'


@pytest.mark.parametrize('stage', ['down', 'list'])
def test_open_transition_wait_is_bounded_and_records_stage_and_cause(stage):
    mem = transition_memory()
    cur = mem['battle']
    cur['card_flow']['stage'] = stage
    for _ in range(p.CARD_LIST_OPEN_WAITS):
        assert p.battle_step(transition_panel(mem), mem) == []
    assert cur['card_flow'] is None
    assert cur['cards_selected'] == cur['cards_used'] == cur['cards_unclassified'] == []
    assert not mem.get('kit_spent')
    record = mem['_records'][-1]
    assert record['decision'] == 'battle_card_open_unclassified'
    assert record['observed_metric']['selection_planned'] is False
    assert record['observed_metric']['stage'] == stage
    assert '一覧' in record['observed_metric']['cause']


def test_picker_rows_on_a_battle_panel_delegate_to_the_list_step():
    # 実切り札一覧がHPパネルと併存して battle 分類のまま残る実画面では、
    # 待機せずそのまま一覧の選択処理へ渡す。
    mem = transition_memory()
    cur = mem['battle']
    screen = picker_panel(mem, 'ゼンマイン')
    assert _card_picker_rows(screen) is True
    assert p.battle_step(screen, mem) == [p.pad('a')]
    assert cur['cards_selected'] == ['ゼンマイン']
    assert cur['card_flow']['stage'] == 'announce'
    assert cur['card_flow']['selection_planned'] is True
    assert mem['_records'][-1]['decision'] == 'battle_card_selected'


def test_open_unclassified_distinguishes_the_menu_and_list_stages():
    mem = transition_memory()
    cur = mem['battle']
    cur['card_flow']['stage'] = 'menu'
    for _ in range(p.CARD_MENU_OPEN_RETRIES + 1):
        p.battle_step(transition_panel(mem), mem)
    record = mem['_records'][-1]
    assert record['decision'] == 'battle_card_open_unclassified'
    assert record['observed_metric']['stage'] == 'menu'
    assert '切り札一覧' not in record['observed_metric']['cause']


@pytest.mark.parametrize('fixture,target', [
    ('g749-roquefort-control-card-list.png', 'クースカン'),
    ('g684-castora-kooskan-list.png', 'クースカン'),
    ('g692-venus-artemis-kooskan-list.png', 'クースカン'),
])
def test_real_card_list_parses_as_text_with_readable_picker_rows(fixture, target):
    # The in-battle picker is a lower-right box classified as text; its card
    # rows and cursor must stay readable for card_list_step.
    screen = parse(read_png(FIXTURES / fixture))
    assert screen.kind == 'text'
    assert _card_picker_rows(screen) is True
    names = [w for _, _, w in _options(screen) if w in ALL_CARD_NAMES]
    assert target in names
    assert _battle_menu_to(screen, target) is not None
